CREATE TABLE [dbo].[ccTipoNotReady](	  [TipoNotReady_id] SMALLINT NOT NULL IDENTITY(1,1)	, [Descripcion] VARCHAR(255) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [Time_Acum] INT NOT NULL DEFAULT((0))	, [Time_xEv] INT NOT NULL DEFAULT((0))	, [Pas_Sup] TINYINT NOT NULL DEFAULT((0))	, [NextStatus] INT NOT NULL DEFAULT((-1))	, [IsSup] INT NOT NULL DEFAULT((0))	, [StatusTipoNotReady] BIT NOT NULL DEFAULT((1))	, CONSTRAINT [PK_ccTipoNotReady] PRIMARY KEY ([TipoNotReady_id] ASC))